/* Generated by gen_packs.py from the original data files: pack "challenges". */
MC.registerPack({"id":"challenges","cards":[{"id":"ch2401","name":"바닥은 용암이다","en":"The Ground is Lava","type":"challenge","enc":true,"unique":false,"text":"비행 모듈식 조우 세트를 사용하여, 공중 특성을 가지고 있거나 얻을 수 있는 히어로만으로 뮤타젠 공식 시나리오에서 승리합니다. 이 시나리오 동안, 아이덴티티가 일상 형태로 변신할 때마다 그 아이덴티티에게 피해 2점을 입힙니다."},{"id":"ch2402","name":"일석이조","en":"Two for One","type":"challenge","enc":true,"unique":false,"text":"패스트볼 스페셜 이벤트로 입힌 피해로 하수인 하나와 빌런을 동시에 격파합니다."},{"id":"ch2403","name":"자석과 금속","en":"Magnets and Metal","type":"challenge","enc":true,"unique":false,"text":"아이언맨, 워머신, 아이언하트, SP//dr 중에서만 히어로를 골라 매그니토 빌런을 격파합니다. 사전 준비 후, 조우 덱에서 포획! 부가 음모를 찾아 공개합니다."},{"id":"ch2404","name":"팀워크가 꿈을 이룬다","en":"Teamwork Makes the Dream Work","type":"challenge","enc":true,"unique":false,"text":"애콜라이트, 다크 라이더스, 리버즈, 블루 문, 내스티 보이즈, 브라더후드, 엑소더스 모듈식 조우 세트를 사용하여 더 후드 빌런을 격파합니다."},{"id":"ch2405","name":"변신의 귀재들","en":"Form Flippers","type":"challenge","enc":true,"unique":false,"text":"앤트맨, 와스프, 스펙트럼, 비전, 섀도캣, 엔젤 중에서 원하는 조합으로 히어로를 골라 엔 사바 누르 시나리오에서 승리합니다."},{"id":"ch2406","name":"꽃의 힘","en":"Flower Power","type":"challenge","enc":true,"unique":false,"text":"그루트 히어로로 집행자 로난 빌런을 격파합니다. 시나리오가 끝날 때 그루트는 생명력이 최대치여야 하며 파워 스톤을 가지고 있어야 합니다."},{"id":"ch2407","name":"부수고 털기: 얼티밋 에디션","en":"Breakin' and Takin': Ultimate Edition","type":"challenge","enc":true,"unique":false,"text":"다음 모듈식 조우 세트를 포함하여 라이노 빌런을 격파합니다: 인피니티 건틀렛, 비행, 괴력, 텔레파시."},{"id":"ch2408","name":"원소 흡수","en":"Absorbing the Elements","type":"challenge","enc":true,"unique":false,"text":"다음 캐릭터들이 (히어로 또는 동료로서) 플레이 영역에 있는 동안 업소빙맨 빌런을 격파합니다: 그루트, 아이스맨, 록슬라이드, 콜로서스."},{"id":"ch2409","name":"유전자 풀 파티","en":"Gene Pool Party","type":"challenge","enc":true,"unique":false,"text":"‘Pool 성향의 히어로만 사용하여 유너스 빌런을 격파합니다. 그 히어로 중 하나는 반드시 피닉스여야 합니다."},{"id":"ch2410","name":"세상엔 속도가 필요해","en":"Need for Speed","type":"challenge","enc":true,"unique":false,"text":"퀵실버 히어로로 한 턴 동안 스피드 데몬 하수인을 세 번 공격합니다."},{"id":"ch2411","name":"대체 누구의 쇼야?","en":"Whose Show is it Anyway?","type":"challenge","enc":true,"unique":false,"text":"스파이더햄 및/또는 데드풀 히어로로 모조 빌런을 격파합니다. 이 시나리오 동안, 쇼 환경은 플레이 영역을 떠날 수 없습니다(쇼 환경의 “공개될 때” 효과는 무시합니다)."},{"id":"ch2412","name":"매드 타이탄의 분노","en":"Wrath of the Mad Titan","type":"challenge","enc":true,"unique":false,"text":"어벤저 및/또는 가디언 히어로만 사용하여 타노스 빌런을 격파합니다. 마지막 일격은 남은 생명력이 1인 히어로만 가할 수 있습니다. 사전 준비를 마친 후, 주요 음모를 스테이지 2A로 진행합니다."},{"id":"ch2413","name":"콜렉션 완성","en":"Complete the Collection","type":"challenge","enc":true,"unique":false,"text":"아무 히어로로 박물관 잠입 시나리오에서 승리합니다. 이 시나리오 동안, 플레이어들은 콜렉션에서 카드를 제거할 수 없으며, 위대한 콜렉션 주요 음모는 콜렉션에 카드가 플레이어당 5장 있어도 더 이상 플레이어들을 패배시키지 않습니다."},{"id":"ch2414","name":"심비오트 난타전","en":"Symbiote Smackdown","type":"challenge","enc":true,"unique":false,"text":"베놈 숙적 조우 세트를 모듈식 조우 세트로 사용하여 베놈 빌런을 격파합니다.\n베놈 히어로, 웹 워리어 히어로, 또는 이름에 “스파이더”가 들어간 히어로만 사용할 수 있습니다. 사전 준비 후, 각 플레이어는 자신의 컬렉션에서 심비오트 슈트 1장을 찾아 자신의 조종하에 플레이 영역에 내려놓고, 그러고 나서 조우 덱에서 격노한 심비오트 1장을 찾아 공개합니다.\n이 시나리오 동안, 각 심비오트 슈트는 영속을 얻으며, 각 격노한 심비오트는 공격받을 때 빌런의 강제 반응을 격발합니다."},{"id":"ch2415","name":"변덕스러운 관중","en":"Fickle Crowds","type":"challenge","enc":true,"unique":false,"text":"아무 히어로로 마곡을 격파합니다. 이 시나리오 동안, 각 빌런 페이즈가 끝날 때 도전자들에서 챔피언으로 시청률 카운터를 플레이어당 1개씩 옮깁니다."},{"id":"ch2416","name":"일상의 영웅들","en":"Everyday Heroes","type":"challenge","enc":true,"unique":false,"text":"어떤 아이덴티티도 히어로 형태로 뒤집지 않고, 아무 히어로로 아무 시나리오에서 승리합니다(각 플레이어는 게임 내내 일상 형태를 유지해야 합니다)."},{"id":"ch2417","name":"신비한 대혼란","en":"Mystic Mayhem","type":"challenge","enc":true,"unique":false,"text":"아담 워록 숙적 조우 세트와 닥터 스트레인지 숙적 조우 세트를 모듈식 조우 세트로 사용하여 에보니 모를 격파합니다. 이 시나리오에는 신비주의자 히어로만 사용할 수 있습니다. 각 빌런 페이즈가 끝날 때, 시작 플레이어는 조우 덱 맨 위 카드를 공개합니다."},{"id":"ch2418","name":"장전 완료","en":"Lock and Load","type":"challenge","enc":true,"unique":false,"text":"오스본 테크, 고블린 장비, 군용 장비 모듈식 조우 세트를 사용하여 크로스본즈를 격파합니다(실험 무기 세트는 제외합니다). 사전 준비 동안, 이 모듈식 세트들에서 무작위로 무기 카드 4장을 골라 함께 섞어 실험 무기 덱을 만듭니다. 나머지 카드는 평소처럼 조우 덱에 섞어 넣습니다. 이 시나리오에는 무기 또는 갑옷 아이덴티티 전용 업그레이드가 있는 히어로만 사용할 수 있습니다."},{"id":"ch2419","name":"외로운 늑대","en":"Lone Wolf","type":"challenge","enc":true,"unique":false,"text":"덱에 동료가 없는 아무 히어로로 1인 플레이하여 스트라이프를 격파합니다(아이덴티티 전용 동료는 성향 카드나 기본 카드로 대체합니다). 이 시나리오 동안, 당신이 하수인을 격파할 때마다 카드 1장을 뽑습니다."},{"id":"ch2420","name":"현장 연구","en":"Field Study","type":"challenge","enc":true,"unique":false,"text":"시간 모듈식 조우 세트를 사용하여 다크 비스트를 격파합니다. 각 플레이어는 일상 형태가 천재 특성을 가진 히어로를 사용해야 합니다. 이 시나리오 동안, 하수인이 공개될 때마다 배경 환경의 “특수” 능력을 해결합니다."},{"id":"ch2421","name":"로봇 대전","en":"Battle of the Bots","type":"challenge","enc":true,"unique":false,"text":"센티넬 모듈식 조우 세트를 사용하여 아무 히어로로 울트론을 격파합니다. 이 시나리오 동안, 드론 하수인은 센티넬 특성을 얻고, 센티넬 하수인은 드론 특성을 얻습니다."},{"id":"ch2422","name":"초록이라 쉽지 않아","en":"Not Easy Being Green","type":"challenge","enc":true,"unique":false,"text":"쉬헐크, 헐크, 가모라, 드랙스 중에서만 히어로를 골라 위험한 사업 시나리오에서 승리합니다. 이 시나리오에서 각 히어로 덱은 수호 성향을 사용해야 합니다. 이 시나리오 동안, 범죄 기업에 악명 카운터가 플레이어당 6개 이상 놓이게 되면, 플레이어들은 게임에서 패배합니다."},{"id":"ch2423","name":"레킹의 심판","en":"The Wreckoning","type":"challenge","enc":true,"unique":false,"text":"아무 히어로로 레킹 크루 시나리오에서 승리합니다. 사전 준비 후, 각 조우 덱에서 다음 장착 카드를 찾아 공개합니다: 마법 쇠지렛대, 쇠공과 쇠사슬, 시선 끄는 도발, 불도저 헬멧. 이 시나리오 동안, 각 빌런은 격파된 빌런마다 음모 +1과 공격 +1을 받습니다."},{"id":"ch2424","name":"절대 무관용","en":"Absolutely Zero Tolerance","type":"challenge","enc":true,"unique":false,"text":"퓨처 패스트 모듈식 조우 세트를 사용하여 와이드어웨이크 프로젝트 시나리오에서 승리합니다. 이 시나리오에는 엑스맨 히어로만 사용할 수 있습니다. 사전 준비 후, 조우 덱에서 바스티온을 찾아 시작 플레이어에게 뒷면 조우 카드로 나누어 줍니다. 각 빌런 페이즈가 끝날 때, 바스티온이 버린 조우 더미나 승점 구역에 있다면, 그를 시작 플레이어에게 뒷면 조우 카드로 나누어 줍니다."}]});
